B.cPM=new A.p("stickyTextColumn",B.t,'Stickies: note text column (default "text").',B.f,null)
B.cFD=new A.p("pinsTable",B.at,"Optional pin-notes table \u2014 numbered notes attached to a POINT on a frame, read and created in the frame review. Absent = the review screen still approves/requests changes, it just has nothing to pin.",B.f,null)
B.cNP=new A.p("pinScreenColumn",B.t,'Pins: owning screen FK column (default "screen").',B.f,null)
B.cKm=new A.p("pinXColumn",B.t,'Pins: FRACTIONAL x within the frame, 0..1 (default "x") \u2014 fractional so a pin stays where it was placed at every zoom and on every device size.',B.f,null)
B.cDG=new A.p("pinYColumn",B.t,'Pins: fractional y within the frame, 0..1 (default "y").',B.f,null)
B.cSC=new A.p("pinOrderColumn",B.t,'Pins: sort key (default "order"). The NUMBER painted on a pin is its position in this order, so numbering stays 1..n with no gaps after a delete.',B.f,null)
B.cGd=new A.p("pinTitleColumn",B.t,'Pins: short note title (default "title").',B.f,null)
